export class PersonPlans {
  readonly personId = input.required<number>();
  readonly personName = input.required<string>();

  protected readonly session = inject(Session);
  private readonly api = inject(PlansApi);

  protected readonly plans = computed(() => this.session.plans().filter((p) => p.personId === this.personId()));
  protected readonly error = signal<string | null>(null);
  private submitting = false;

  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    start: new FormControl('', { nonNullable: true }),
    every: new FormControl('', { nonNullable: true }),
    end: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.error.set(null);
        this.form.reset({ amount: '', start: '', every: '', end: '' }, { emitEvent: false });
      });
    });
  }

  protected fieldId(name: string): string {
    return `plan-form-${name}-${this.personId()}`;
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const value = this.form.getRawValue();
    const amount = value.amount.trim();
    const start = value.start.trim();
    const every = value.every.trim();
    const end = value.end.trim();
    if (!AMOUNT_PATTERN.test(amount)) {
      this.error.set('Enter an amount of 0.00 or more with up to two decimals.');
      return;
    }
    if (!/^\d{1,9}$/.test(every) || Number(every) < 1) {
      this.error.set('Repeat every whole number of days, 1 or more.');
      return;
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(end)) {
      this.error.set('Enter an end date.');
      return;
    }
    const from = start === '' ? this.session.today() : start;
    if (from !== null && end < from) {
      this.error.set('The end cannot be before the start.');
      return;
    }
    this.submitting = true;
    try {
      const plan = await this.api.add(sheetId, this.personId(), { amount, start: start === '' ? null : start, every: Number(every), end });
      if (this.session.sheetId() === sheetId) {
        this.session.plans.update((ps) => [...ps.filter((p) => p.id !== plan.id), plan].sort((a, b) => a.id - b.id));
      }
      this.form.reset({ amount: '', start: '', every: '', end: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(planError(e));
    } finally {
      this.submitting = false;
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';
import type { Claim } from '../claims/claims-api';

/** A person's plan: a DRAFT claim of its amount (two decimals) for each plan date, its start and
 *  then every so many days, up to its end; with how many claims it has made so far. */
export interface Plan {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number;
  end: string;
  generated: number;
}

/** A plan as the form submits it: a blank start takes the sheet's today. */
export interface PlanForm {
  amount: string;
  start: string | null;
  every: number;
  end: string;
}

/** A generate's result: the claims made, in the order they were made, and the sheet's plans now. */
export interface Generated {
  claims: Claim[];
  plans: Plan[];
}

@Injectable({ providedIn: 'root' })
export class PlansApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's plans, in the order they were added. */
  list(sheetId: string): Promise<Plan[]> {
    return firstValueFrom(this.http.get<Plan[]>(`${this.url(sheetId)}/plans`, { headers: this.headers() }));
  }

  add(sheetId: string, personId: number, form: PlanForm): Promise<Plan> {
    return firstValueFrom(this.http.post<Plan>(`${this.url(sheetId)}/people/${personId}/plans`, form, { headers: this.headers() }));
  }

  /** Make the claims every plan on the sheet is due by the sheet's today. */
  generate(sheetId: string): Promise<Generated> {
    return firstValueFrom(this.http.post<Generated>(`${this.url(sheetId)}/plans/generate`, null, { headers: this.headers() }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function planError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) {
    return 'Enter an amount of 0.00 or more with up to two decimals, a whole number of days of 1 or more and an end date.';
  }
  if (e instanceof HttpErrorResponse && e.status === 422) return 'Give an end on or after the start and repeat every 1 day or more.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That person is no longer on the sheet.';
  return otherError(e);
}
